class Solution:
    def minimumHealth(self, damage: list[int], armor: int) -> int:
        return 1 + sum(damage) - min(armor, max(damage))

class Solution {
public:
    long long minimumHealth(vector<int>& damage, int armor) {
        long long total = 0;
        int maxD = 0;
        for (int d : damage) {
            total += d;
            maxD = max(maxD, d);
        }
        return 1 + total - min(armor, maxD);
    }
};

class Solution {
    public long minimumHealth(int[] damage, int armor) {
        long total = 0;
        int maxD = 0;
        for (int d : damage) {
            total += d;
            maxD = Math.max(maxD, d);
        }
        return 1 + total - Math.min(armor, maxD);
    }
}

/**
 * @param {number[]} damage
 * @param {number} armor
 * @return {number}
 */
var minimumHealth = function(damage, armor) {
    let total = 0n;
    let maxD = 0;
    for (const d of damage) {
        total += BigInt(d);
        if (d > maxD) maxD = d;
    }
    const absorbed = BigInt(Math.min(armor, maxD));
    return Number(1n + total - absorbed);
};
